long even = 0, odd = 0; // Initialize counters for even and odd digits
num = abs(num); // Convert the number to its absolute value to handle negative numbers

while (num > 0) {
    long digit = num % 10; // Extract the last digit
    if (digit % 2 == 0) {
        even++; // Increment even counter if the digit is even
    } else {
        odd++; // Increment odd counter if the digit is odd
    }
    num /= 10; // Remove the last digit from the number
}
return std::make_tuple(even, odd); // Return the tuple containing the counts of even and odd digits

