long result = operand[0]; // Initialize the result with the first operand
for (size_t i = 0; i < op.size(); ++i) {
    switch (op[i]) {
        case "+":
            result += operand[i + 1];
            break;
        case "-":
            result -= operand[i + 1];
            break;
        case "*":
            result *= operand[i + 1];
            break;
        case "//":
            result /= operand[i + 1];
            break;
        case "**":
            result = pow(result, operand[i + 1]);
            break;
        default:
            // Handle other cases if needed
            break;
    }
} 
return result; // Return the final result

